#include "bme280_driver.h"
#include <stddef.h>

int bme280_init(bme280_t *dev, bme280_reg_read_t read_cb, bme280_reg_write_t write_cb)
{
    if (!dev || !read_cb || !write_cb) {
        return -1;
    }
    dev->read = read_cb;
    dev->write = write_cb;
    return 0;
}

static int bme280_write_reg(bme280_t *dev, uint8_t reg, uint8_t val)
{
    return dev->write(reg, &val, 1U);
}

static int bme280_read_regs(bme280_t *dev, uint8_t start_reg, uint8_t *buf, uint32_t len)
{
    return dev->read(start_reg, buf, len);
}

int bme280_set_mode(bme280_t *dev, bme280_mode_t mode)
{
    uint8_t ctrl_meas;
    if (bme280_read_regs(dev, BME280_REG_CTRL_MEAS, &ctrl_meas, 1U) != 0) {
        return -1;
    }
    ctrl_meas = (ctrl_meas & 0xFC) | (uint8_t)mode;
    return bme280_write_reg(dev, BME280_REG_CTRL_MEAS, ctrl_meas);
}

int bme280_set_oversampling(bme280_t *dev, bme280_osrs_t osrs_t, bme280_osrs_t osrs_p, bme280_osrs_t osrs_h)
{
    uint8_t ctrl_meas, ctrl_hum;
    /* humidity oversampling */
    ctrl_hum = (uint8_t)osrs_h & 0x07U;
    if (bme280_write_reg(dev, BME280_REG_CTRL_HUM, ctrl_hum) != 0) {
        return -1;
    }
    /* temperature and pressure oversampling */
    if (bme280_read_regs(dev, BME280_REG_CTRL_MEAS, &ctrl_meas, 1U) != 0) {
        return -1;
    }
    ctrl_meas = ((uint8_t)osrs_t << 5) | ((uint8_t)osrs_p << 2) | (ctrl_meas & 0x03U);
    return bme280_write_reg(dev, BME280_REG_CTRL_MEAS, ctrl_meas);
}

int bme280_read_raw(bme280_t *dev, uint32_t *press_raw, uint32_t *temp_raw, uint16_t *hum_raw)
{
    uint8_t buf[8];
    if (bme280_read_regs(dev, BME280_REG_PRESS_MSB, buf, 8U) != 0) {
        return -1;
    }
    *press_raw = ((uint32_t)buf[0] << 12) | ((uint32_t)buf[1] << 4) | ((uint32_t)buf[2] >> 4);
    *temp_raw  = ((uint32_t)buf[3] << 12) | ((uint32_t)buf[4] << 4) | ((uint32_t)buf[5] >> 4);
    *hum_raw   = ((uint16_t)buf[6] << 8) | (uint16_t)buf[7];
    return 0;
}

