#ifndef BME280_DRIVER_H
#define BME280_DRIVER_H

#include <stdint.h>

/* Callback type definitions */
typedef int (*bme280_reg_read_t)(uint8_t reg, uint8_t *buf, uint32_t len);
typedef int (*bme280_reg_write_t)(uint8_t reg, const uint8_t *buf, uint32_t len);

/* Driver context */
typedef struct {
    bme280_reg_read_t  read;
    bme280_reg_write_t write;
} bme280_t;

/* Register addresses (bus offsets) */
#define BME280_REG_ID          0xD0U
#define BME280_REG_RESET       0xE0U
#define BME280_REG_CTRL_HUM    0xF2U
#define BME280_REG_CTRL_MEAS   0xF4U
#define BME280_REG_CONFIG      0xF5U
#define BME280_REG_PRESS_MSB   0xF7U
#define BME280_REG_PRESS_LSB   0xF8U
#define BME280_REG_PRESS_XLSB  0xF9U
#define BME280_REG_TEMP_MSB    0xFAU
#define BME280_REG_TEMP_LSB    0xFBU
#define BME280_REG_TEMP_XLSB   0xFCU
#define BME280_REG_HUM_MSB     0xFDU
#define BME280_REG_HUM_LSB     0xFEU

/* Configuration enums */
typedef enum {
    BME280_MODE_SLEEP = 0x00,
    BME280_MODE_FORCED = 0x01,
    BME280_MODE_NORMAL = 0x03
} bme280_mode_t;

typedef enum {
    BME280_OSRS_SKIP = 0x00,
    BME280_OSRS_1    = 0x01,
    BME280_OSRS_2    = 0x02,
    BME280_OSRS_4    = 0x03,
    BME280_OSRS_8    = 0x04,
    BME280_OSRS_16   = 0x05
} bme280_osrs_t;

/* Public API */
int bme280_init(bme280_t *dev, bme280_reg_read_t read_cb, bme280_reg_write_t write_cb);
int bme280_set_mode(bme280_t *dev, bme280_mode_t mode);
int bme280_set_oversampling(bme280_t *dev, bme280_osrs_t osrs_t, bme280_osrs_t osrs_p, bme280_osrs_t osrs_h);
int bme280_read_raw(bme280_t *dev, uint32_t *press_raw, uint32_t *temp_raw, uint16_t *hum_raw);

#endif /* BME280_DRIVER_H */

