#include <stdio.h>
#include "bme280_driver.h"

/* Mock I2C read/write functions for demonstration */
static int mock_read(uint8_t reg, uint8_t *buf, uint32_t len)
{
    (void)reg; /* suppress unused parameter warning */
    /* In a real implementation, fill buf with data from the device */
    for (uint32_t i = 0; i < len; ++i) {
        buf[i] = 0x00U;
    }
    return 0;
}

static int mock_write(uint8_t reg, const uint8_t *buf, uint32_t len)
{
    (void)reg; (void)buf; (void)len; /* suppress unused warnings */
    return 0;
}

int main(void)
{
    bme280_t dev;
    if (bme280_init(&dev, mock_read, mock_write) != 0) {
        printf("Failed to init driver\n");
        return -1;
    }
    if (bme280_set_oversampling(&dev, BME280_OSRS_1, BME280_OSRS_1, BME280_OSRS_1) != 0) {
        printf("Failed to set oversampling\n");
        return -1;
    }
    if (bme280_set_mode(&dev, BME280_MODE_FORCED) != 0) {
        printf("Failed to set mode\n");
        return -1;
    }
    uint32_t press_raw = 0, temp_raw = 0;
    uint16_t hum_raw = 0;
    if (bme280_read_raw(&dev, &press_raw, &temp_raw, &hum_raw) != 0) {
        printf("Failed to read raw data\n");
        return -1;
    }
    printf("Raw pressure: %u, temperature: %u, humidity: %u\n", press_raw, temp_raw, hum_raw);
    return 0;
}

