#include "w25q64jv_driver.h"

/* Helper: send a command with optional address and dummy bytes */
static int w25q64jv_tx_rx(w25q64jv_t *dev, const uint8_t *tx_buf, uint8_t *rx_buf, size_t len)
{
    if (!dev || !dev->transfer) {
        return -1;
    }
    return dev->transfer(tx_buf, rx_buf, len);
}

int w25q64jv_init(w25q64jv_t *dev, w25q64jv_spi_transfer_t transfer_cb)
{
    if (!dev || !transfer_cb) {
        return -1;
    }
    dev->transfer = transfer_cb;
    return 0;
}

int w25q64jv_write_enable(w25q64jv_t *dev)
{
    uint8_t cmd = W25Q64JV_CMD_WRITE_ENABLE;
    return w25q64jv_tx_rx(dev, &cmd, NULL, 1);
}

int w25q64jv_write_disable(w25q64jv_t *dev)
{
    uint8_t cmd = W25Q64JV_CMD_WRITE_DISABLE;
    return w25q64jv_tx_rx(dev, &cmd, NULL, 1);
}

int w25q64jv_read_status1(w25q64jv_t *dev, uint8_t *status)
{
    uint8_t tx[2] = { W25Q64JV_CMD_READ_STATUS1, 0x00 };
    uint8_t rx[2] = {0};
    int ret = w25q64jv_tx_rx(dev, tx, rx, 2);
    if (ret == 0 && status) {
        *status = rx[1];
    }
    return ret;
}

int w25q64jv_read_jedec_id(w25q64jv_t *dev, uint8_t *buf)
{
    uint8_t tx[4] = { W25Q64JV_CMD_JEDEC_ID, 0x00, 0x00, 0x00 };
    uint8_t rx[4] = {0};
    int ret = w25q64jv_tx_rx(dev, tx, rx, 4);
    if (ret == 0 && buf) {
        buf[0] = rx[1]; // Manufacturer ID
        buf[1] = rx[2]; // Memory Type
        buf[2] = rx[3]; // Capacity
    }
    return ret;
}

int w25q64jv_read_data(w25q64jv_t *dev, uint32_t addr, uint8_t *buf, size_t len)
{
    if (!buf || len == 0) {
        return -1;
    }
    uint8_t tx[4];
    tx[0] = W25Q64JV_CMD_READ_DATA;
    tx[1] = (addr >> 16) & 0xFFu;
    tx[2] = (addr >> 8) & 0xFFu;
    tx[3] = addr & 0xFFu;
    /* Send command+address, then read data */
    int ret = w25q64jv_tx_rx(dev, tx, NULL, 4);
    if (ret) return ret;
    return w25q64jv_tx_rx(dev, NULL, buf, len);
}

int w25q64jv_page_program(w25q64jv_t *dev, uint32_t addr, const uint8_t *buf, size_t len)
{
    if (!buf || len == 0 || len > W25Q64JV_PAGE_SIZE) {
        return -1;
    }
    uint8_t header[4];
    header[0] = W25Q64JV_CMD_PAGE_PROGRAM;
    header[1] = (addr >> 16) & 0xFFu;
    header[2] = (addr >> 8) & 0xFFu;
    header[3] = addr & 0xFFu;
    int ret = w25q64jv_tx_rx(dev, header, NULL, 4);
    if (ret) return ret;
    return w25q64jv_tx_rx(dev, buf, NULL, len);
}

int w25q64jv_sector_erase(w25q64jv_t *dev, uint32_t addr)
{
    uint8_t tx[4];
    tx[0] = W25Q64JV_CMD_SECTOR_ERASE;
    tx[1] = (addr >> 16) & 0xFFu;
    tx[2] = (addr >> 8) & 0xFFu;
    tx[3] = addr & 0xFFu;
    return w25q64jv_tx_rx(dev, tx, NULL, 4);
}

int w25q64jv_chip_erase(w25q64jv_t *dev)
{
    /* Chip erase is not listed explicitly; use block erase 64KB covering whole memory */
    /* For simplicity, perform a sequence of 64KB block erases covering 8 MB (max address 0x7FFFFF) */
    uint32_t addr;
    int ret = 0;
    for (addr = 0; addr < 0x800000u; addr += W25Q64JV_BLOCK64K_SIZE) {
        ret = w25q64jv_tx_rx(dev, (uint8_t[]){W25Q64JV_CMD_BLOCK_ERASE_64K,
                                            (addr >> 16) & 0xFFu,
                                            (addr >> 8) & 0xFFu,
                                            addr & 0xFFu}, NULL, 4);
        if (ret) break;
    }
    return ret;
}

