#include <stdio.h>
#include "w25q64jv_driver.h"

/* Simple SPI transfer stub for demonstration – replace with real ESP32 SPI driver. */
static int spi_transfer_stub(const uint8_t *tx, uint8_t *rx, size_t len)
{
    /* In a real implementation you would assert CS, send tx, read rx, deassert CS. */
    (void)tx; (void)rx; (void)len;
    return 0; /* pretend success */
}

int main(void)
{
    w25q64jv_t flash;
    if (w25q64jv_init(&flash, spi_transfer_stub) != 0) {
        printf("Failed to init driver\n");
        return -1;
    }

    if (w25q64jv_write_enable(&flash) != 0) {
        printf("Write Enable failed\n");
        return -1;
    }

    uint8_t jedec[3];
    if (w25q64jv_read_jedec_id(&flash, jedec) == 0) {
        printf("JEDEC ID: %02X %02X %02X\n", jedec[0], jedec[1], jedec[2]);
    }

    /* Example: read first 16 bytes */
    uint8_t data[16];
    if (w25q64jv_read_data(&flash, 0x000000, data, sizeof(data)) == 0) {
        printf("Data at 0x000000: ");
        for (size_t i = 0; i < sizeof(data); ++i) {
            printf("%02X ", data[i]);
        }
        printf("\n");
    }

    return 0;
}

